'use strict';
const menuButton=document.querySelector('.menu-toggle'),navigation=document.querySelector('#navigation');
function closeMenu(){menuButton.setAttribute('aria-expanded','false');menuButton.setAttribute('aria-label','Open navigation');navigation.classList.remove('open');}
menuButton.addEventListener('click',()=>{const open=menuButton.getAttribute('aria-expanded')!=='true';menuButton.setAttribute('aria-expanded',String(open));menuButton.setAttribute('aria-label',open?'Close navigation':'Open navigation');navigation.classList.toggle('open',open);});
navigation.querySelectorAll('a').forEach(link=>link.addEventListener('click',closeMenu));
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&navigation.classList.contains('open')){closeMenu();menuButton.focus();}});
document.addEventListener('click',event=>{if(!event.target.closest('.header'))closeMenu();});
window.matchMedia('(min-width:801px)').addEventListener('change',event=>{if(event.matches)closeMenu();});
const constructs={
att:{code:'INDIVIDUAL EVALUATION / ATT',title:'Believing in the value.',description:'A favorable or unfavorable evaluation of using AI-enabled digital technologies in project work, including perceived effectiveness, quality, and timeliness.',example:'“I believe these tools can make my project management more effective.”'},
sn:{code:'SOCIAL EXPECTATIONS / SN',title:'What important others expect.',description:'Perceived approval, encouragement, or expectations from supervisors, colleagues, and other important people about digital or AI technology use.',example:'“My supervisor encourages me to use new digital tools.”'},
pbc:{code:'PERCEIVED CAPABILITY / PBC',title:'Feeling able to take part.',description:'Perceived ability, confidence, access, resources, and opportunity to use digital technologies. This is one proposed pathway linking network support to collaboration frequency.',example:'“I have the tools, confidence, and time to explore a new way of working.”'},
sns:{code:'THE NETWORK EXTENSION / SNS',title:'Support makes connection possible.',description:'Perceived access to colleagues who provide practical help, advice, examples, discussion, and troubleshooting when using digital or AI-related tools.',example:'“I have a colleague I can turn to when a digital tool becomes a challenge.”'},
dcf:{code:'SELF-REPORTED FREQUENCY / DCF',title:'How often we collaborate digitally.',description:'The reported regularity of exchanging project ideas and collaborating with colleagues using digital tools. Measured with a single frequency-oriented agreement item, rather than usage logs.',example:'“I often exchange project ideas and collaborate with colleagues using digital tools.”'}};
const constructButtons=document.querySelectorAll('[data-construct]');
constructButtons.forEach(button=>{button.setAttribute('aria-pressed',String(button.classList.contains('selected')));button.addEventListener('click',()=>{const item=constructs[button.dataset.construct];constructButtons.forEach(other=>{other.classList.toggle('selected',other===button);other.setAttribute('aria-pressed',String(other===button));});document.querySelector('#construct-code').textContent=item.code;document.querySelector('#construct-title').textContent=item.title;document.querySelector('#construct-description').textContent=item.description;document.querySelector('#construct-example').textContent=item.example;});});
const models=[{label:'Traditional TPB (baseline)',value:45.5,gain:'+0.0',description:'Baseline model with attitude, subjective norm, and perceived behavioral control.'},{label:'TPB + network support',value:62.3,gain:'+16.8',description:'Additional explained variance when social network support enters the model.'},{label:'TPB + network support + experience',value:63.2,gain:'+17.7',description:'Additional explained variance over baseline; experience adds 0.9 pp beyond network support.'}];
const modelButtons=document.querySelectorAll('[data-model]');
modelButtons.forEach(button=>{button.setAttribute('aria-pressed',String(button.classList.contains('active')));button.addEventListener('click',()=>{const model=models[Number(button.dataset.model)];modelButtons.forEach(other=>{other.classList.toggle('active',other===button);other.setAttribute('aria-pressed',String(other===button));});document.querySelector('#comparison-label').textContent=model.label;document.querySelector('#comparison-value').textContent=model.value.toFixed(1)+'%';document.querySelector('#comparison-bar').style.setProperty('--bar',(model.value/75*100).toFixed(2)+'%');const gain=document.querySelector('#gain');gain.replaceChildren(document.createTextNode(model.gain));const unit=document.createElement('span');unit.textContent='pp';gain.append(unit);document.querySelector('#gain-description').textContent=model.description;});});
const citation='Nguyen, Tuan Duc, and Long D. Nguyen. “Network-Extended Theory of Planned Behavior for Digital Collaboration in Construction Project Management.” Revised manuscript. Research materials: https://github.com/praiseCM/digital-collab.';
document.querySelector('#copy-citation').addEventListener('click',async()=>{const status=document.querySelector('#copy-status');try{if(!navigator.clipboard?.writeText)throw new Error('Clipboard unavailable');await navigator.clipboard.writeText(citation);status.textContent='Citation copied to clipboard.';}catch{status.textContent=citation;}});
document.querySelectorAll('.method-details details').forEach(detail=>detail.addEventListener('toggle',()=>{detail.querySelector('summary > span:last-child').textContent=detail.open?'−':'+';}));
document.querySelector('#year').textContent=String(new Date().getFullYear());
if('IntersectionObserver'in window){const observer=new IntersectionObserver(entries=>{entries.forEach(entry=>{if(entry.isIntersecting)navigation.querySelectorAll('a').forEach(link=>{const active=link.getAttribute('href')==='#'+entry.target.id;link.classList.toggle('active',active);if(active)link.setAttribute('aria-current','location');else link.removeAttribute('aria-current');});});},{rootMargin:'-15% 0px -60% 0px',threshold:0});document.querySelectorAll('main section[id]').forEach(section=>observer.observe(section));}

constructButtons.forEach(button=>button.addEventListener('click',()=>{document.querySelector('.model-panel').dataset.active=button.dataset.construct;const detail=document.querySelector('.construct-detail');detail.classList.remove('detail-changing');requestAnimationFrame(()=>detail.classList.add('detail-changing'));}));
